// Validate audio metadata from Phase 3
const audioData = $input.first().json;

if (!audioData.audio_url || typeof audioData.audio_url !== 'string') {
  throw new Error('Missing or invalid audio_url field');
}

if (!audioData.script_id) {
  throw new Error('Missing script_id field');
}

if (!audioData.audio_duration_seconds || audioData.audio_duration_seconds < 30) {
  throw new Error('Audio duration must be at least 30 seconds');
}

if (audioData.audio_duration_seconds > 3600) {
  throw new Error('Audio duration exceeds 1 hour limit');
}

return {
  json: {
    audio_url: audioData.audio_url,
    script_id: audioData.script_id,
    audio_duration_seconds: audioData.audio_duration_seconds,
    language: audioData.language || 'en-US',
    video_title: audioData.title || 'Generated Video',
    is_valid: true,
    validated_at: new Date().toISOString()
  }
};

