// Build FFmpeg filter graph for video composition
const audioData = items[0].json;
const assets = items[1]?.json || {};

const timeline = {
  width: parseInt(process.env.VIDEO_WIDTH || 1920),
  height: parseInt(process.env.VIDEO_HEIGHT || 1080),
  fps: parseInt(process.env.VIDEO_FPS || 30),
  duration: audioData.audio_duration_seconds,
  bitrate: process.env.VIDEO_BITRATE || '5000k',
  codec: process.env.VIDEO_CODEC || 'libx264',
  audio_bitrate: process.env.AUDIO_BITRATE || '192k',
  audio_codec: process.env.AUDIO_CODEC || 'aac',
  transition_duration: parseFloat(process.env.TRANSITION_DURATION || 0.5),
  background_blur: parseInt(process.env.BACKGROUND_BLUR || 5),
  text_overlay_enabled: process.env.TEXT_OVERLAY_ENABLED === 'true',
  script_id: audioData.script_id,
  audio_url: audioData.audio_url
};

return [
  {
    json: timeline
  }
];

// Generate YouTube Shorts format (9:16 vertical)
const audioData = items[0].json;
const shortsConfig = {
  width: parseInt(process.env.SHORTS_WIDTH || 1080),
  height: parseInt(process.env.SHORTS_HEIGHT || 1920),
  fps: parseInt(process.env.SHORTS_FPS || 30),
  max_duration: parseInt(process.env.SHORTS_DURATION_MAX || 60),
  bitrate: process.env.SHORTS_BITRATE || '3000k',
  codec: process.env.VIDEO_CODEC || 'libx264',
  input_video: `/tmp/n8n-video/${audioData.script_id}-long-form.mp4`,
  output_path: `/tmp/n8n-video/${audioData.script_id}-shorts.mp4`,
  aspect_ratio: '9:16',
  trim_to_duration: Math.min(audioData.audio_duration_seconds, 59)
};

return [
  {
    json: shortsConfig
  }
];

