const shortsPath = `/tmp/n8n-video/${$node['Process - Validate Audio'].json.script_id}-shorts.mp4`;

return {
  json: {
    long_form_video: {
      path: longFormPath,
      resolution: `${$node['Generate - Visual Timeline'].json.width}x${$node['Generate - Visual Timeline'].json.height}`,
      fps: $node['Generate - Visual Timeline'].json.fps,
      bitrate: $node['Generate - Visual Timeline'].json.bitrate,
      codec: 'h264',
      format: 'mp4',
      expected_size_mb: Math.ceil(($node['Process - Validate Audio'].json.audio_duration_seconds * parseInt($node['Generate - Visual Timeline'].json.bitrate)) / 8000),
      status: 'pending_validation'
    },
    shorts_video: {
