      fps: $node['Create - YouTube Shorts'].json.fps,
      bitrate: $node['Create - YouTube Shorts'].json.bitrate,
      codec: 'h264',
      format: 'mp4',
      max_duration: $node['Create - YouTube Shorts'].json.max_duration,
      expected_size_mb: Math.ceil((Math.min($node['Process - Validate Audio'].json.audio_duration_seconds, 59) * parseInt($node['Create - YouTube Shorts'].json.bitrate)) / 8000),
